#include "ClipboardLiveStore.h"
#include <algorithm>
namespace private_input::activity {namespace {
std::string identity(const Id&sender,const Id&event){return uuidText(sender)+":"+uuidText(event);}
Json item(const ClipboardLiveOpened&o){auto hash=sha256(bytes(o.text));return Json::object({{"event",uuidText(o.event)},{"hash",base64(Data(hash.begin(),hash.end()))},{"sender",uuidText(o.sender)},{"issuedAt",o.issuedAt},{"expiresAt",o.expiresAt},{"text",o.text}});}
void prune(Json&j,uint64_t now){for(auto at=j["seen"].fields.begin();at!=j["seen"].fields.end();)if(at->second.at("expiresAt").num()<=now)at=j["seen"].fields.erase(at);else ++at;auto&cache=j["texts"].items;cache.erase(std::remove_if(cache.begin(),cache.end(),[&](const auto&r){return r.at("expiresAt").num()<=now;}),cache.end());auto&compat=j["compat"].items;compat.erase(std::remove_if(compat.begin(),compat.end(),[&](const auto&r){return r.at("expiresAt").num()<=now;}),compat.end());}
}
Json ClipboardLiveStore::initial(){return Json::object({{"version",1},{"scope",""},{"group",""},{"epoch",0},{"cursor",0},{"ready",false},{"seen",Json::object()},{"texts",Json::array()},{"outbox",Json()},{"outboxText",""},{"outboxContext",Json()},{"compat",Json::array()}});}
ClipboardLiveStore::ClipboardLiveStore(Json j,std::function<void(const Json&)>p):state(j.kind==Json::Kind::null?initial():std::move(j)),persist(std::move(p)){if(!state.has("outboxContext"))state["outboxContext"]=Json();require(state.at("version").num()==1&&state.at("cursor").num()<=uint64_t(INT64_MAX)&&state.at("seen").fields.size()<=512&&state.at("texts").items.size()<=20&&state.at("compat").items.size()<=20&&state.dump().size()<=4194304,"live state bounds");(void)state.at("ready").boolean();}
void ClipboardLiveStore::save(const Json&j){require(j.dump().size()<=4194304,"live state limit");persist(j);state=j;}
void ClipboardLiveStore::configure(const ClipboardLiveGrant&g){if(state.at("scope").str()==g.scope&&state.at("group").str()==uuidText(g.group)&&state.at("epoch").num()==g.epoch)return;auto next=initial();next["scope"]=g.scope;next["group"]=uuidText(g.group);next["epoch"]=g.epoch;save(next);}
Json ClipboardLiveStore::pending(uint64_t now){auto next=state;prune(next,now);if(next.at("outbox").kind!=Json::Kind::null&&next.at("outbox").at("expiresAt").num()<=now){next["outbox"]=Json();next["outboxText"]="";next["outboxContext"]=Json();}if(next.dump()!=state.dump())save(next);return state.at("outbox");}
void ClipboardLiveStore::stage(const ClipboardLiveGrant&g,const std::string&text,uint64_t now,const Json&context){configure(g);auto old=pending(now);require(old.kind==Json::Kind::null,"live outbox pending");auto event=sealClipboardLive(g,text,now);auto next=state;next["outbox"]=event;next["outboxText"]=text;next["outboxContext"]=context;save(next);}
bool ClipboardLiveStore::receive(Json&next,const ClipboardLiveOpened&o,uint64_t now){auto id=identity(o.sender,o.event);auto&seen=next["seen"];bool known=seen.has(id);if(known&&seen.at(id).has(o.kind)){require(seen.at(id).at(o.kind).str()==o.digest,"live same-kind equivocation");return false;}if(!known){require(seen.fields.size()<512,"live receipt quota");seen[id]=Json::object({{"expiresAt",o.expiresAt}});}seen[id][o.kind]=o.digest;seen[id]["expiresAt"]=std::max(seen.at(id).at("expiresAt").num(),o.expiresAt);if(known)return false;auto&cache=next["texts"].items;cache.push_back(item(o));while(cache.size()>20||Json::array(cache).dump().size()>262144)cache.erase(cache.begin());return true;}
ClipboardLiveBatch ClipboardLiveStore::apply(const ClipboardLiveGrant&g,const Json&r,const Json&published,uint64_t now){configure(g);auto after=cursor();validateClipboardLiveResponse(r,after,published);auto next=state;prune(next,now);ClipboardLiveBatch result;result.cold=!ready();std::vector<ClipboardLiveOpened>verified;for(const auto&row:r.at("items").items){auto raw=unbase64(row.at("wire").str());verified.push_back(openClipboardProjection(row.at("kind").str(),Json::parse(std::string(raw.begin(),raw.end()),131072,24,16384),g,now));}for(const auto&opened:verified)if(receive(next,opened,now)&&!result.cold&&opened.sender!=g.parent)result.fresh.push_back(item(opened));
 if(published.kind!=Json::Kind::null){require(next.at("outbox").dump()==published.dump(),"live outbox changed in flight");auto body=next.at("outboxText").str();auto own=openClipboardProjection("live",published,g,now);require(own.text==body,"live staged plaintext changed");(void)receive(next,own,now);auto&compat=next["compat"].items;compat.push_back(Json::object({{"event",published.at("event")},{"text",body},{"expiresAt",published.at("expiresAt")},{"context",next.at("outboxContext")}}));while(compat.size()>20||Json::array(compat).dump().size()>1310720)compat.erase(compat.begin());next["outbox"]=Json();next["outboxText"]="";next["outboxContext"]=Json();}
 next["cursor"]=result.cold?r.at("head"):r.at("next");next["ready"]=true;save(next);return result;}
bool ClipboardLiveStore::importLegacy(const ClipboardLiveGrant&g,const Json&wire,uint64_t now,bool mayApply,Json*value){configure(g);auto opened=openClipboardProjection("legacy",wire,g,now);auto next=state;prune(next,now);bool fresh=receive(next,opened,now);if(next.dump()!=state.dump())save(next);if(value)*value=item(opened);return fresh&&ready()&&mayApply&&opened.sender!=g.parent;}
std::vector<Json>ClipboardLiveStore::compatibility(uint64_t now)const{std::vector<Json>rows;for(const auto&r:state.at("compat").items)if(r.at("expiresAt").num()>now)rows.push_back(r);return rows;}
void ClipboardLiveStore::compatibilityQueued(const Id&event){auto next=state;auto&rows=next["compat"].items;rows.erase(std::remove_if(rows.begin(),rows.end(),[&](const auto&r){return parseId(r.at("event").str())==event;}),rows.end());if(next.dump()!=state.dump())save(next);}
bool ClipboardLiveStore::knows(const Id&sender,const Id&event)const{return state.at("seen").has(identity(sender,event));}
}

namespace private_input::activity {
void ClipboardLiveStore::fallbackToCompatibility(uint64_t now){auto wire=pending(now);if(wire.kind==Json::Kind::null)return;auto next=state;auto&rows=next["compat"].items;rows.push_back(Json::object({{"event",wire.at("event")},{"text",next.at("outboxText")},{"expiresAt",wire.at("expiresAt")},{"context",next.at("outboxContext")}}));while(rows.size()>20||Json::array(rows).dump().size()>1310720)rows.erase(rows.begin());next["outbox"]=Json();next["outboxText"]="";next["outboxContext"]=Json();save(next);}
void ClipboardLiveStore::clearPending(bool clearTexts){auto next=state;next["outbox"]=Json();next["outboxText"]="";next["outboxContext"]=Json();next["compat"]=Json::array();if(clearTexts)next["texts"]=Json::array();save(next);}
}
